contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // We accept an amount to forward to addToBalance.
    function run(uint256 amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        // ensure this test contract can forward the requested amount
        require(address(this).balance >= amount);

        // observe before-values
        uint256 beforeRecorded = c.getBalance(address(this)); if (__ESBMC_reverted()) return;
        uint256 beforeContractEth = address(c).balance;

        // call addToBalance and record whether it reverted
        bool reverted;
        c.addToBalance{value: amount}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // observe after-values
        uint256 afterRecorded = c.getBalance(address(this)); if (__ESBMC_reverted()) return;
        uint256 afterContractEth = address(c).balance;

        // If the call succeeded then: (1) c's Ether balance increased exactly by amount,
        // and (2) the recorded user balance for this test did not increase by more than amount.
        // If it reverted, no guarantees.
        assert(reverted || (afterContractEth == beforeContractEth + amount && afterRecorded <= beforeRecorded + amount));
    }

    receive() external payable {}
}

